<!doctype html>
<html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#0f172a;font-size:12px}h1{color:#1d4ed8;margin:0}.header{display:flex;justify-content:space-between;border-bottom:2px solid #2563eb;padding-bottom:18px;margin-bottom:24px}.meta{text-align:right;color:#475569}table{width:100%;border-collapse:collapse;margin-top:22px}th{background:#eff6ff;color:#1e3a8a;text-align:left}th,td{padding:10px;border-bottom:1px solid #e2e8f0}.number{text-align:right}.totals{width:45%;margin-left:auto;margin-top:20px}.totals td{padding:6px 10px}.grand{font-size:15px;font-weight:bold;color:#1d4ed8}.footer{margin-top:35px;color:#64748b}</style></head><body><div class="header"><div><h1>{{ $organization->name }}</h1><p>Quotation</p></div><div class="meta"><strong>{{ $quotation->number }}</strong><br>Status: {{ ucfirst($quotation->status) }}<br>Issued: {{ $quotation->issued_at?->format('M j, Y') ?? 'Draft' }}<br>Expires: {{ $quotation->expires_at?->format('M j, Y') ?? '—' }}</div></div><table><thead><tr><th>Description</th><th class="number">Qty</th><th class="number">Unit price</th><th class="number">Discount</th><th class="number">Tax</th><th class="number">Total</th></tr></thead><tbody>@foreach($quotation->items as $item)<tr><td><strong>{{ $item->name }}</strong><br>{{ $item->description }}</td><td class="number">{{ $item->quantity }}</td><td class="number">{{ number_format($item->unit_price,2) }}</td><td class="number">{{ number_format($item->discount_amount,2) }}</td><td class="number">{{ number_format($item->tax_amount,2) }}</td><td class="number">{{ number_format($item->line_total,2) }}</td></tr>@endforeach</tbody></table><table class="totals"><tr><td>Subtotal</td><td class="number">{{ number_format($quotation->subtotal,2) }} {{ $quotation->currency }}</td></tr><tr><td>Discount</td><td class="number">-{{ number_format($quotation->discount_total,2) }}</td></tr><tr><td>Tax</td><td class="number">{{ number_format($quotation->tax_total,2) }}</td></tr><tr class="grand"><td>Total</td><td class="number">{{ number_format($quotation->total,2) }} {{ $quotation->currency }}</td></tr></table>@if($quotation->terms)<div class="footer"><strong>Terms</strong><p>{{ $quotation->terms }}</p></div>@endif</body></html>
